    // soit la taille d'affichage — y compris en haut et en bas, un pourcentage
    // vertical se résolvant lui aussi sur la largeur en CSS.
    const margeEnPourcent = (mm) => `${(Math.max(0, Math.min(40, Number(mm) || 0)) / 210) * 100}%`;

