    const handleSaveDocumentPrefix = async (kind) => {
        if (!supabaseClient || !sbUser || sbUser.id === 'guest' || !activeOrganizationId) return;
        const prefix = (kind === 'quote' ? quotePrefixInput : invoicePrefixInput).trim();
        if (!prefix || prefix.length > 12) {
            showToast("Le préfixe doit faire entre 1 et 12 caractères.", "error");
            return;
        }
        setPrefixSaving(prev => ({ ...prev, [kind]: true }));
        try {
            const { error } = await supabaseClient.rpc('set_document_prefix', {
                p_org_id: activeOrganizationId, p_kind: kind, p_prefix: prefix
            });
            if (error) throw error;
            showToast(`Préfixe des ${kind === 'quote' ? 'devis' : 'factures'} mis à jour : ${prefix}`, "success");
        } catch (err) {
            showToast(`Échec : ${err.message}`, "error");
        } finally {
            setPrefixSaving(prev => ({ ...prev, [kind]: false }));
        }
    };
    // B3 (2026-08-18) — Cette identité n'a plus vocation à être écrite dans un
    // vrai devis : un compte réel démarre avec des champs légaux VIDES (voir
    // emptyCompany plus bas), suivant le même garde estModeDemo que les
    // clients/projets/devis de démonstration (cf. commit "Réserver les
    // données de démonstration au Mode Invité"). demoCompany ne sert plus
    // qu'à peupler le Mode Invité, pour que la démo reste utilisable sans
    // qu'un utilisateur réel puisse envoyer un devis sous un NIF ivoirien
    // fictif sans même s'en rendre compte.
    const defaultCommercialSettings = {
        bankName: '',
        bankAccount: '',
        bankSwift: '',
        // 2026-09-06 — Paiement mobile local (Orange Money, Wave, Moov Money) :
        // plus pertinent que Stripe/PayPal pour la clientèle d'ikadevis en
        // Afrique de l'Ouest. Numéros optionnels, affichés sur le PDF
        // uniquement s'ils sont renseignés (même logique que le RIB).
        orangeMoneyNumber: '',
        waveNumber: '',
        moovMoneyNumber: '',
        defaultDepositRate: 0,
        retentionRate: 0,
        retentionDuration: '12 mois',
        quoteEmailSubject: 'Votre devis {{Numero_Devis}} — {{Entreprise}}',
        quoteEmailBody: 'Bonjour {{Nom_Client}},\n\nVeuillez trouver votre devis {{Numero_Devis}} d’un montant de {{Montant_Devis}}.\n\nNous restons à votre disposition.\n\nCordialement,\n{{Entreprise}}',
        invoiceEmailSubject: 'Votre facture {{Numero_Facture}} — {{Entreprise}}',
        invoiceEmailBody: 'Bonjour {{Nom_Client}},\n\nVeuillez trouver votre facture {{Numero_Facture}} d’un montant de {{Montant_Facture}}.\n\nCordialement,\n{{Entreprise}}'
    };
    const demoCompany = {
        name: 'IKADEVIS BTP',
        managerName: '',
        tagline: 'BTP - Fabrications - Aménagement - Signalétique',
        phone: '',
        email: 'contact@ikadevis.com',
        address: "Abidjan, Côte d'Ivoire",
        nif: '',
        rccm: '',
        currency: 'FCFA',
        paymentSchedule: [
            { label: 'Acompte à la signature et démarrage des travaux', pct: 40 },
            { label: "Situation intermédiaire / Avancement gros œuvre & hors d'eau", pct: 30 },
            { label: 'Second œuvre, finitions et équipements', pct: 20 },
            { label: 'Solde à la réception définitive et remise des clés', pct: 10 }
        ],
        quoteValidity: "30 jours à compter de la date d'émission.",
        internalDocRoles: ['admin'],
        clientQuoteTemplate: 'synthese',
        vatRates: [18, 10, 0],
        vatExemptionNote: '',
        commercialSettings: { ...defaultCommercialSettings },
        brandColor: PDF_BRAND_COLOR_DEFAULT,
        pdfFont: 'modern',
        pdfHeaderAlignment: 'left'
    };
    const defaultPaymentSchedule = [
        { label: 'Acompte à la signature et au démarrage', pct: 40 },
        { label: 'Situation intermédiaire / Avancement des travaux', pct: 30 },
        { label: 'Finitions et équipements', pct: 20 },
        { label: 'Solde à la réception', pct: 10 }
    ];
    const emptyCompany = {
        name: '', managerName: '', tagline: '', phone: '', email: '', address: '', nif: '', rccm: '',
        currency: 'FCFA',
        paymentSchedule: defaultPaymentSchedule,
        quoteValidity: "30 jours à compter de la date d'émission.",
        internalDocRoles: ['admin'],
        clientQuoteTemplate: 'synthese',
        vatRates: [18, 10, 0],
        vatExemptionNote: '',
        commercialSettings: { ...defaultCommercialSettings },
        brandColor: PDF_BRAND_COLOR_DEFAULT,
        pdfFont: 'modern',
        pdfHeaderAlignment: 'left'
    };
    const estModeDemoCompany = !sbUser || sbUser.id === 'guest';
    const defaultCompany = estModeDemoCompany ? demoCompany : emptyCompany;

    // Directives d'identification légale (2026-09-10) :
    // « les seuls champs obligatoires : le nom prénom et nom de la société,
    // même le numéro de téléphone peut rester éphémère sauf en cas de l'usage
    // de certaines fonctionnalités comme l'envoi par WhatsApp. »
    //
    // Seul le nom ou la raison sociale de l'entreprise est strictement requis pour
    // identifier le document. L'adresse, l'e-mail, le téléphone, le NIF et le RCCM
    // sont purement facultatifs et ne bloquent en aucun cas l'émission d'une facture,
    // le téléchargement d'un PDF ou l'envoi d'un devis.
    const CHAMPS_LEGAUX_BLOQUANTS = ['name'];
    const CHAMPS_LEGAUX_RECOMMANDES = [];
    const getMissingLegalFields = (info) => CHAMPS_LEGAUX_BLOQUANTS.filter(k => !(info?.[k] || '').trim());
    const champsLegauxRecommandesManquants = () => [];

    // B2 (2026-08-18) — Garde-fou réutilisable pour TOUTE prestation de
    // main-d'œuvre, présente ou future (pas seulement maçonnerie/carrelage,
    // le cas qui a révélé le bug). Le principe : chaque prestation choisit
    // elle-même son mode de tarification — journalier (unit 'j', un tarif
    // par équipe/jour) ou direct (m², ml, u, forfait — un tarif par unité
    // produite). RENDEMENT_MO n'a de sens que pour convertir un métré en
    // nombre de jours ; l'exiger ou l'interdire selon le mode choisi
    // empêche le bug source de B2 : un tarif direct traité comme un tarif
    // journalier (ou l'inverse) sans que rien ne le signale avant l'envoi
    // d'un devis sous-chiffré au client.
    // B2bis (2026-08-19) — Les deux modèles de rémunération de la main-d'œuvre
    // du métier, rendus explicites et interchangeables en un geste :
    //
    //   « régie »    unit 'j'  + rendement + formule qui DIVISE par RENDEMENT_MO
    //                → on paie la journée ; si le rendement n'est pas tenu,
    //                  c'est l'entreprise qui absorbe le surcoût.
    //   « tâche »    unit m²/ml/u + formule qui NE divise PAS
    //                → prix ferme à l'unité produite ; c'est le tâcheron qui
    //                  absorbe un rendement plus faible.
    //
    // Arithmétiquement les deux donnent le même coût TANT QUE le rendement est
    // tenu (12 000/j ÷ 15 m²/j = 800 F/m²). Ce qui diffère, c'est qui porte le
    // risque — d'où l'intérêt de choisir en connaissance de cause plutôt que de
    // le subir. Basculer suppose de changer l'unité ET toutes les formules qui
    // utilisent la ressource : c'est précisément l'oubli qui a causé B2, donc
    // le logiciel fait les deux ensemble.
    const isDailyUnit = (unit) => unit === 'j' || unit === 'j-eq';

    const formulaToDaily = (formula) => {
        const f = (formula || '').trim();
        if (!f || /RENDEMENT_MO/.test(f)) return f;
        // Parenthéser pour que la division porte sur toute l'expression :
        // 'SURFACE * COUCHES' / REND ≠ 'SURFACE * (COUCHES / REND)'.
        return `(${f}) / RENDEMENT_MO`;
    };

    const formulaToTask = (formula) => {
        let f = (formula || '').trim();
        if (!/RENDEMENT_MO/.test(f)) return f;
        f = f.replace(/\s*\/\s*RENDEMENT_MO/g, '').trim();
        // Retirer un parenthésage devenu inutile, seulement s'il enveloppe
        // toute l'expression (sinon on casserait 'A * (B + C)').
        if (f.startsWith('(') && f.endsWith(')')) {
            let depth = 0, wrapsAll = true;
            for (let i = 0; i < f.length; i++) {
                if (f[i] === '(') depth++;
                else if (f[i] === ')') { depth--; if (depth === 0 && i < f.length - 1) { wrapsAll = false; break; } }
            }
            if (wrapsAll) f = f.slice(1, -1).trim();
        }
        return f;
    };

    const getLaborUnitFormulaMismatch = (unit, formula) => {
        const dividesByYield = /RENDEMENT_MO/.test(formula || '');
        if (unit === 'j' && !dividesByYield) {
            return "Tarif journalier : la formule doit diviser par RENDEMENT_MO (sinon le tarif/jour est facturé comme un tarif à l'unité, sans tenir compte du rendement).";
        }
        if (unit !== 'j' && dividesByYield) {
            return "Tarif à l'unité (pas journalier) : la formule ne doit pas diviser par RENDEMENT_MO (sinon chaque unité facturée est divisée une seconde fois par le rendement).";
        }
        return null;
    };

    const [isSaveQuoteModalOpen, setIsSaveQuoteModalOpen] = useState(false);
    const [saveQuoteForm, setSaveQuoteForm] = useState({ clientName: '', projectRef: '', notes: '' });
    const [viewingSavedQuote, setViewingSavedQuote] = useState(null);
    const [viewingInvoice, setViewingInvoice] = useState(null);
    // 2026-09-10 — Suivi des règlements & encaissements de factures
    const [paymentModalData, setPaymentModalData] = useState(null); // Facture sur laquelle saisir un paiement
    const [receiptModalData, setReceiptModalData] = useState(null); // { facture, payment } pour afficher / imprimer la quittance
    const [creditNoteModalData, setCreditNoteModalData] = useState(null); // Facture sur laquelle émettre un avoir rectificatif
    const [selectedInvoiceIds, setSelectedInvoiceIds] = useState(new Set()); // Opérations groupées sur factures
    const [previewInvoiceModal, setPreviewInvoiceModal] = useState(null); // Modale d'aperçu fidèle du document PDF
    const [emailComposerModal, setEmailComposerModal] = useState(null); // Modale d'envoi & relance e-mail avec templates
    // Liste+détail façon Zoho Books (2026-08-22) : le menu « Nouveau » qui
    // propose les devis facturables remplace l'ancienne carte toujours visible.
